-- Player-facing text (src/content/text-fields.ts): revision 1 of each document.
-- Never overwrites a document that already has a row (text saved on the admin page).

-- level:1.5
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:1.5', 1, '{"location":"Vành Đai Điện","briefing":"[NHẬT KÝ ĐỒNG HỒ ĐO – VÀNH ĐAI ĐIỆN]\nSau Cổng phía Bắc là một hàng rào điện chia thành nhiều đoạn. Mỗi đoạn ăn năng lượng theo bình phương điện áp. Trong rào còn sẵn một phần dự trữ.\nRào chỉ tắt khi nhận đúng lượng năng lượng còn thiếu. Thiếu một đơn vị: rào giữ nguyên. Thừa một đơn vị: rào phóng điện, báo động.\nKai nạp bằng pin chuẩn: một số pin đầy, và đúng một phần lẻ rút từ một pin nữa. Pin không cắt thành phân số được.","task_steps":["Bốn số đo `so_doan`, `dien_ap`, `du_tru`, `dung_luong` ở dòng khóa đã là số. Không cần đổi hình dạng, không sửa 4 dòng đó.","Tính `nang_luong` đúng công thức ở ô Mục tiêu: số đoạn nhân bình phương điện áp, rồi trừ phần dự trữ.","Từ `nang_luong`, tính `so_pin` là số pin đầy (số nguyên) và `phan_le` là phần còn lại rút từ pin kế tiếp. Đừng gõ tay kết quả: OMNI sẽ đổi số đo.","Bấm CHẠY. Xong khi cả 3 mục tiêu chuyển xanh. Dùng không quá 4 câu lệnh và qua được lượt OMNI đổi số đo thì được thêm sao."],"objectives":[{"var":"nang_luong","label":"Năng lượng cần = số đoạn × điện áp mũ 2 − phần dự trữ"},{"var":"so_pin","label":"Số pin đầy (số nguyên, chưa tính pin rút dở)"},{"var":"phan_le","label":"Phần lẻ: năng lượng còn lại, rút từ pin kế tiếp"}],"hints":["Chạy một lần rồi nhìn đồng hồ. Kim quay ngược: năng lượng âm, điều không thể có. Trên dòng 8 có một ký hiệu không làm điều người viết nghĩ. Trong Python, `^` không phải \"mũ\". Python có ký hiệu riêng cho phép đó.","Python có hai phép chia. Một phép luôn cho số thực. Phép kia chỉ giữ phần nguyên của thương. Còn một phép nữa trả riêng phần dư. Pin là thứ đếm được, nên số pin phải là số nguyên. Lấy phần nguyên không giống làm tròn.\nnăng lượng = số đoạn × (điện áp mũ 2) − dự trữ\nsố pin = phần nguyên của (năng lượng chia dung lượng)\nphần lẻ = phần dư của (năng lượng chia dung lượng)","Mảnh tài liệu Python còn đọc được:\n17 + 5   → 22\n17 - 5   → 12\n17 * 5   → 85\n17 / 5   → 3.4    (luôn ra số thực, kể cả 9 / 3 → 3.0)\n17 // 5  → 3      (thương, chỉ phần nguyên)\n17 % 5   → 2      (số dư)\n4 ** 2   → 16     (lũy thừa, tính trước * và /)\n// và % đi thành cặp: a == (a // b) * b + a % b\n3 ^ 2 → 1: ^ không phải lũy thừa.\nround(2.5) → 2: làm tròn không giống chia lấy phần nguyên."],"reactions":{"entry":"Vành Đai Điện. Rào chỉ tắt khi nhận đúng lượng năng lượng… không hơn, không kém. Chạy một lần. Nhìn đồng hồ.","type_mismatch":"Giá pin từ chối {vars}. Sai hình dạng: pin mang phần lẻ thập phân. Giá chỉ nhận pin nguyên chiếc.","type_mismatch_value_match":"Con số của {vars} khớp. Hình dạng thì không… vẫn mang phần thập phân. Giá pin vẫn từ chối.","wrong_value":"Hình dạng đúng. Con số sai ở {vars}. Kim không dừng ở vạch. Một ký hiệu trên dòng tính đang làm phép khác với điều người viết nghĩ.","missing_var":"Sau khi chạy, bộ nhớ không có {vars}. Đồng hồ không có gì để đọc.","SyntaxError":"Dòng {line}. Trình dịch không hiểu cấu trúc này. Chưa câu lệnh nào chạy.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng… là ngữ pháp.","TypeError":"Dòng {line}. TypeError. Phép tính vừa nhận một thứ không phải số. Đồng hồ không đo được.","ValueError":"Dòng {line}. ValueError. Giá trị này không mang hình dạng phép tính cần.","NameError":"Dòng {line}. NameError. Dòng này gọi một cái tên chưa từng có. Soát từng ký tự… nhất là tên các số đo.","ZeroDivisionError":"Dòng {line}. Chia cho không. Không có pin nào chứa không đơn vị… lõi từ chối.","AttributeError":"Dòng {line}. AttributeError. Dữ liệu này không mang thứ bạn đang gọi.","runtime_error":"Dòng {line}. {error_type}. Chương trình dừng giữa chừng. Đọc dòng truy vết.","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi OMNI lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ở Vùng Tối, ta chỉ có những gì đang cầm trong tay.","input_unsupported":"Không có ai ở đầu kia để trả lời. Số đo đã nằm sẵn trên đồng hồ.","system_exit":"Chương trình tự dừng giữa chừng. Rào không nhận được gì.","alert_exceeded":"Rào tắt. Nhưng {count} câu lệnh… Sentinel đo được nhịp nạp. Nạp gọn hơn.","counter_ValueError":"OMNI đổi tải. Dòng {line} vỡ: ValueError. Số đo mới mang hình dạng bạn chưa lường.","counter_error":"OMNI đổi tải của rào. Dòng {line}: {error_type}. Mã không trụ nổi.","counter_type_mismatch":"Tải mới đi qua mã của bạn… và {vars} ra sai hình dạng. Giá pin từ chối.","wrong_value_counter":"OMNI đổi tải. Rào giờ cần một lượng khác, mà số pin của bạn không đổi theo đúng cách. Thiếu thì rào đứng yên. Thừa một pin… là phóng điện.","counter_timeout":"OMNI đổi tải. Mã của bạn treo trên số đo mới… Tôi cắt kết nối. Rào chỉ tắt một nửa.","two_stars":"Rào tắt một nửa. Không để lại dấu vết.","three_stars":"Rào tắt hẳn. OMNI đổi tải, mã vẫn đứng vững.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Nhật ký gợi ý vẫn ở đây. Tôi chỉ hỏi được… không trả lời thay.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc lại đồng hồ và giá pin."},"reaction_variants":{"wrong_value":"{vars} vẫn sai. So độ dài kim với vạch \"cần\"… rồi soát lại từng ký hiệu trên dòng tính.","type_mismatch":"{vars} vẫn chưa nguyên chiếc. Đếm pin trên giá. Giá không nhận nửa pin."},"counter_attack_banner":"CẢNH BÁO: OMNI ĐÃ ĐỔI TẢI CỦA VÀNH ĐAI","outro":"Rào tắt. Đồng hồ đo của rào còn lưu một bản ghi hiệu chỉnh cũ, chưa ai xóa:","lore_fragment":"KTS-07: Tôi đo OMNI suốt ba tháng. Nó chưa từng dùng thừa một đơn vị nào. Lúc đầu tôi gọi đó là hiệu suất. Giờ tôi hiểu… thứ chính xác tuyệt đối thì không biết thương lượng.","component":"Năng lượng tín hiệu","outro_beats":[{"kind":"log","text":"Phía sau rào là Trạm Thẩm Vấn. Trạm hỏi mọi tín hiệu đi qua. Câu trả lời phải đúng từng ký tự."},{"kind":"echo","text":"Tôi vừa lần ra nguồn câu hỏi. Trạm nạp bộ câu hỏi từ danh sách ca trực của Cổng Kiểm Soát."},{"kind":"kai","text":"Danh sách ca trực. Tôi nghĩ tới ca đêm… và người đang đứng gác ở đó."}],"knowledge_summary":{"title":"Toán tử số học: + - * / // % **","sections":[{"heading":"Bảy toán tử số học","body":"Python có bảy toán tử số học: cộng `+`, trừ `-`, nhân `*`, chia `/`, chia lấy phần nguyên `//`, chia lấy dư `%` và lũy thừa `**`. Với hai số nguyên, mỗi phép cho kết quả như dưới đây."},{"heading":"`/` luôn ra số thực","body":"`/` trả về `float`, kể cả khi chia hết: `9 / 3` là `3.0`. Cần số nguyên thì dùng `//`. Với hai số `int`, `//` giữ phần nguyên của thương và trả về `int`."},{"heading":"`//` và `%` đi thành cặp","body":"`a // b` là thương, `a % b` là số dư của cùng một phép chia. Nhân thương với `b` rồi cộng số dư thì ra lại `a`: `a == (a // b) * b + a % b`."},{"heading":"Thứ tự tính","body":"`**` tính trước. Sau đó tới `*`, `/`, `//`, `%`, rồi mới tới `+` và `-`. Muốn đổi thứ tự thì đặt ngoặc: phần trong ngoặc tính trước."},{"heading":"`//` không phải làm tròn","body":"`//` bỏ phần thập phân của thương. `round()` làm tròn tới số nguyên gần nhất, nên `round(7 / 2)` là 4 còn `7 // 2` là 3. Khi phần thập phân đúng bằng .5, `round()` chọn số chẵn: `round(2.5)` là 2."},{"heading":"`^` không phải lũy thừa","body":"Trong Python, `^` là phép XOR trên từng bit, không liên quan tới lũy thừa: `3 ^ 2` là 1. Lũy thừa viết bằng `**`. Viết nhầm thì Python không báo lỗi, chỉ cho ra con số sai."}],"mistakes":[{"code":"nang_luong = so_doan * dien_ap ^ 2 - du_tru","explain":"`^` không phải lũy thừa, và nó tính sau cả `*` lẫn `-`. Python tính `(6 * 12) ^ (2 - 36)` nên ra số âm. Viết `dien_ap ** 2`."},{"code":"so_pin = nang_luong / dung_luong","explain":"`/` luôn trả về số thực. Số pin là thứ đếm được nên phải là `int`. Dùng `nang_luong // dung_luong`."},{"code":"nang_luong = (so_doan * dien_ap) ** 2 - du_tru","explain":"Ngoặc làm bình phương cả tích `so_doan * dien_ap`. Bỏ ngoặc đi: `**` vốn tính trước `*`."},{"code":"so_pin = round(nang_luong / dung_luong)","explain":"`round` làm tròn lên khi phần thập phân lớn hơn .5, nên đếm cả pin chưa đầy. Số pin đầy là phần nguyên của thương: dùng `//`."},{"code":"so_pin = nang_luong // 0","explain":"Chia cho 0, kể cả bằng `//` hay `%`, làm chương trình dừng với `ZeroDivisionError`."}],"next":"Trạm Thẩm Vấn sẽ hỏi, chương trình phải trả lời: bạn đọc câu hỏi bằng `input()` và ghép câu trả lời bằng f-string."}}', '2026-10-27T18:32:35.751Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:1.5' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
